mapper.select:
SELECT t.id AS id, t.name AS name, t.kind AS kind, t.description AS description, t.sort_order AS sort_order, t.created_by_user_id AS created_by_user_id, t.created_at AS created_at, t.updated_at AS updated_at, count(s.id) AS skill_count FROM tag t LEFT JOIN skill_tag st ON st.tag_id = t.id LEFT JOIN skill s ON s.id = st.skill_id AND s.status = 'PUBLISHED'
AND t.kind = #{kind}
GROUP BY t.id ORDER BY t.kind, t.sort_order, t.name

SELECT id, name, kind, description, sort_order, created_by_user_id, created_at, updated_at
FROM tag
WHERE name = #{name}
